<template>
    <div class="row">
        <Head title="Validation Forms" />

        <div v-for="demo in demos" :key="demo.id" :class="demo.icon ? 'md:col-6' : 'col-12'">
            <Card :title="demo.icon ? demo.title : undefined" :icon="demo.icon" :card-header-class="demo.icon ? 'card-header-rose' : 'card-header-rose card-header-text'">
                <template v-if="!demo.icon" #header>
                    <div class="card-text"><h4 class="card-title">{{ demo.title }}</h4></div>
                </template>

                <form :id="demo.id" novalidate @submit.prevent="submitDemo($event, demo)" @input="refreshDemo($event, demo)">
                    <div v-for="field in demo.fields" :key="field.name" class="mb-3" :class="demo.icon ? 'form-group' : 'row align-items-baseline'">
                        <label v-if="!demo.icon" :for="`${demo.id}-${field.name}`" class="sm:col-2 col-form-label">
                            {{ field.label }}
                        </label>
                        <div :class="!demo.icon && (field.source ? 'sm:col-6' : 'sm:col-7')">
                            <div :class="{ row: field.source }">
                                <div
                                    v-for="control in field.source ? [field.source, field] : [field]"
                                    :key="control.name"
                                    :class="{ 'sm:col-6': field.source, 'bmd-form-group': demo.icon }"
                                >
                                    <label v-if="demo.icon" :for="`${demo.id}-${control.name}`" class="bmd-label-floating">
                                        {{ control.label }}<span aria-hidden="true"> *</span>
                                    </label>
                                    <input
                                        :id="`${demo.id}-${control.name}`"
                                        :name="control.name"
                                        :type="control.type || 'text'"
                                        class="form-control"
                                        :class="{ 'is-invalid': errors[demo.id]?.[control.name] }"
                                        :aria-label="control.inputLabel"
                                        :aria-invalid="errors[demo.id]?.[control.name] ? 'true' : undefined"
                                        :aria-describedby="descriptionIds(demo, control)"
                                        :placeholder="demo.icon ? ' ' : undefined"
                                        required
                                        v-bind="control.attributes"
                                    />
                                    <div v-if="errors[demo.id]?.[control.name]" :id="`${demo.id}-${control.name}-error`" class="invalid-feedback">
                                        {{ errors[demo.id][control.name] }}
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div v-if="field.hint" :id="`${demo.id}-${field.name}-hint`" :class="field.source ? 'sm:col-4' : 'sm:col-3'">
                            <code>{{ field.hint }}</code>
                        </div>
                    </div>
                    <small v-if="demo.icon" class="description">* Required fields</small>
                    <div v-if="demo.newsletter" class="mt-2">
                        <Checkbox
                            v-model:checked="newsletter"
                            name="newsletter"
                            required
                            :aria-invalid="errors[demo.id]?.newsletter ? 'true' : undefined"
                            :aria-describedby="errors[demo.id]?.newsletter ? 'newsletter-error' : undefined"
                        >
                            Subscribe to newsletter
                        </Checkbox>
                        <p v-if="errors[demo.id]?.newsletter" id="newsletter-error" class="fg-danger mb-0">{{ errors[demo.id].newsletter }}</p>
                    </div>
                    <p v-if="validated[demo.id]" class="fg-success mb-0 mt-2" role="status">Validation passed.</p>
                </form>

                <template #footer>
                    <button type="submit" :form="demo.id" class="btn btn-rose">{{ demo.submitLabel }}</button>
                </template>
            </Card>
        </div>
    </div>
</template>

<script>
import { Head } from '@inertiajs/vue3';
import Card from '@scaffold/components/Card.vue';
import Checkbox from '@scaffold/components/Checkbox.vue';

const emailField = { name: 'email', label: 'Email Address', type: 'email', attributes: { autocomplete: 'off' } };
const passwordField = { name: 'password', label: 'Password', type: 'password', attributes: { autocomplete: 'off' } };

export default {
    name: 'ValidationFormsDemo',
    components: { Card, Checkbox, Head },
    layout: { pageTitle: 'Validation Forms' },
    data() {
        return {
            newsletter: false,
            errors: {},
            validated: {},
            demos: [
                {
                    id: 'register-validation',
                    title: 'Register Form',
                    icon: 'mail_outline',
                    submitLabel: 'Register',
                    newsletter: true,
                    fields: [
                        emailField,
                        passwordField,
                        { name: 'confirmation', label: 'Confirm Password', type: 'password', matches: 'password', attributes: { autocomplete: 'off' } },
                    ],
                },
                {
                    id: 'login-validation',
                    title: 'Login Form',
                    icon: 'contacts',
                    submitLabel: 'Login',
                    fields: [emailField, passwordField],
                },
                {
                    id: 'type-validation',
                    title: 'Type Validation',
                    submitLabel: 'Validate Inputs',
                    fields: [
                        { name: 'text', label: 'Required Text', hint: 'required' },
                        { name: 'email', label: 'Email', type: 'email', hint: 'type="email"' },
                        { name: 'number', label: 'Number', type: 'number', hint: 'type="number"', attributes: { step: 'any' } },
                        { name: 'url', label: 'URL', type: 'url', hint: 'type="url"' },
                        {
                            name: 'match',
                            label: 'Equal to',
                            inputLabel: 'Matching text',
                            hint: 'matches: "source"',
                            matches: 'source',
                            attributes: { placeholder: 'Matching text' },
                            source: { name: 'source', inputLabel: 'Source text', attributes: { placeholder: 'Source text' } },
                        },
                    ],
                },
                {
                    id: 'range-validation',
                    title: 'Range Validation',
                    submitLabel: 'Validate Inputs',
                    fields: [
                        { name: 'min-length', label: 'Min Length', hint: 'minlength="5"', attributes: { minlength: 5 } },
                        { name: 'max-length', label: 'Max Length', hint: 'pattern=".{1,5}"', attributes: { pattern: '.{1,5}', title: 'Enter at most 5 characters.' } },
                        { name: 'range', label: 'Range', type: 'number', hint: 'min="6" max="10"', attributes: { min: 6, max: 10, step: 'any' } },
                        { name: 'min-value', label: 'Min Value', type: 'number', hint: 'min="6"', attributes: { min: 6, step: 'any' } },
                        { name: 'max-value', label: 'Max Value', type: 'number', hint: 'max="6"', attributes: { max: 6, step: 'any' } },
                    ],
                },
            ],
        };
    },
    methods: {
        descriptionIds(demo, field) {
            const id = `${demo.id}-${field.name}`;
            return [
                field.hint ? `${id}-hint` : '',
                this.errors[demo.id]?.[field.name] ? `${id}-error` : '',
            ].filter(Boolean).join(' ') || undefined;
        },
        validate(form, demo) {
            for (const field of demo.fields.filter((item) => item.matches)) {
                const input = form.elements.namedItem(field.name);
                const source = form.elements.namedItem(field.matches);
                const mismatch = input.value && input.value !== source.value;
                input.setCustomValidity(mismatch ? 'The two fields must match.' : '');
            }

            const invalidFields = [...form.elements].filter((input) => input.name && input.willValidate && !input.validity.valid);
            this.errors[demo.id] = Object.fromEntries(invalidFields.map((input) => [input.name, input.validationMessage]));
            return invalidFields;
        },
        submitDemo(event, demo) {
            const invalidFields = this.validate(event.currentTarget, demo);
            this.validated[demo.id] = !invalidFields.length;
            invalidFields[0]?.focus();
        },
        refreshDemo(event, demo) {
            this.validated[demo.id] = false;
            if (this.errors[demo.id]) {
                this.validate(event.currentTarget, demo);
            }
        },
    },
};
</script>
